impl Case {
    pub const ALL: [Self; 14] = [Self::Nominative, Self::Accusative, Self::Genitive, Self::Partitive, Self::Illative, Self::Inessive, Self::Elative, Self::Allative, Self::Adessive, Self::Ablative, Self::Translative, Self::Terminative, Self::Abessive, Self::Comitative];
}

